LAYERS = ('source', 'native_host', 'mojo_host', 'installed_host', 'target_runtime', 'binary_abi')
SESSION_EXPORTS = ('lmb_open', 'lmb_load', 'lmb_attach', 'lmb_poll', 'lmb_map_info', 'lmb_map_read', 'lmb_map_write', 'lmb_stats', 'lmb_last_error', 'lmb_detach', 'lmb_close')
GENERIC_EXPORTS = ('lmb_object_open_v1', 'lmb_object_configure_program_v1', 'lmb_object_load_v1', 'lmb_object_program_info_v1', 'lmb_object_map_info_v1', 'lmb_object_close_v1', 'lmb_object_release_v1', 'lmb_generic_last_error_v1', 'lmb_object_map_lookup_v1', 'lmb_object_map_update_v1', 'lmb_program_test_run_v1', 'lmb_object_attach_v1', 'lmb_link_close_v1', 'lmb_buffer_open_v1', 'lmb_buffer_poll_v1', 'lmb_buffer_close_v1', 'lmb_object_ref_v1', 'lmb_object_unref_v1', 'lmb_object_gen_v1', 'lmb_object_gen_check_v1')
HOST_HEADERS = {'src/' + name for name in ('libbpf.h', 'bpf.h', 'btf.h', 'libbpf_common.h', 'libbpf_legacy.h', 'libbpf_version.h', 'bpf_endian.h')}
PRODUCER_HEADERS = {'src/' + name for name in ('bpf_helpers.h', 'bpf_helper_defs.h', 'bpf_tracing.h', 'bpf_core_read.h', 'usdt.bpf.h')}
KINDS = {'function', 'inline', 'callback', 'typedef', 'record', 'enum', 'enumerator', 'member', 'macro', 'alias'}


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _canonical(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(',', ':')).encode()


def _formatted(value: object) -> bytes:
    return (json.dumps(value, indent=2, sort_keys=True) + '\n').encode()


def _safe_path(value: object) -> bool:
    if not isinstance(value, str) or not value or '\\' in value:
        return False
    path = PurePosixPath(value)
    return not path.is_absolute() and '..' not in path.parts and '.' not in path.parts and str(path) == value and not value.startswith(('build/', '.git/'))


def _read(root: Path, path: str) -> bytes:
    if not _safe_path(path):
        raise ValueError('unsafe repository-relative path ' + repr(path))
    target = root / path
    if not target.resolve().is_relative_to(root.resolve()):
        raise ValueError('source path escapes repository: ' + path)
    return target.read_bytes()


def _schema_errors(value: object, schema: dict, document: dict, at: str = '$') -> list[str]:
    """Apply only the closed, sealed schema vocabulary used by this contract.

    This intentionally is not a general JSON Schema implementation. Unsupported
    keywords fail instead of being ignored; malformed-document agreement tests
    exercise the schema checks separately from semantic inventory assertions.
    """
    errors = []
    known = {'$schema', '$id', 'title', '$defs', '$ref', 'type', 'const', 'enum', 'properties', 'required', 'additionalProperties', 'items', 'minimum', 'minLength', 'pattern', 'anyOf'}
    unknown = set(schema) - known
    if unknown:
        return [at + ': unsupported schema keywords ' + ','.join(sorted(unknown))]
    if '$ref' in schema:
        pointer = schema['$ref']
        if not pointer.startswith('#/$defs/') or pointer[8:] not in document['$defs']:
            return [at + ': unresolved schema reference ' + pointer]
        return _schema_errors(value, document['$defs'][pointer[8:]], document, at)
    if 'anyOf' in schema:
        alternatives = [_schema_errors(value, item, document, at) for item in schema['anyOf']]
        if all(alternatives):
            return [at + ': no admitted schema alternative'] + min(alternatives, key=len)
    if 'const' in schema and _canonical(value) != _canonical(schema['const']):
        errors.append(at + ': expected constant ' + repr(schema['const']))
    if 'enum' in schema and all(_canonical(value) != _canonical(item) for item in schema['enum']):
        errors.append(at + ': unknown vocabulary value ' + repr(value))
    if 'type' in schema:
        names = schema['type'] if isinstance(schema['type'], list) else [schema['type']]
        types = {'object': isinstance(value, dict), 'array': isinstance(value, list), 'string': isinstance(value, str), 'integer': type(value) is int, 'number': type(value) in (int, float), 'boolean': type(value) is bool, 'null': value is None}
        if not any(types.get(name, False) for name in names):
            return errors + [at + ': invalid type; expected ' + repr(names)]
    if isinstance(value, dict):
        props = schema.get('properties', {})
        for name in schema.get('required', []):
            if name not in value:
                errors.append(at + '.' + name + ': required field missing')
        if schema.get('additionalProperties') is False:
            errors += [at + '.' + name + ': unknown schema field' for name in sorted(set(value) - set(props))]
        for name in sorted(set(value) & set(props)):
            errors += _schema_errors(value[name], props[name], document, at + '.' + name)
    if isinstance(value, list) and 'items' in schema:
        for i, item in enumerate(value):
            errors += _schema_errors(item, schema['items'], document, at + '[' + str(i) + ']')
    if isinstance(value, str):
        if 'minLength' in schema and len(value) < schema['minLength']:
            errors.append(at + ': empty string')
        if 'pattern' in schema and re.search(schema['pattern'], value) is None:
            errors.append(at + ': pattern mismatch')
    if type(value) in (int, float) and 'minimum' in schema and value < schema['minimum']:
        errors.append(at + ': below minimum')
    return errors


def _closed(value: object, fields: set[str], at: str, errors: list[str]) -> bool:
    if not isinstance(value, dict):
        errors.append(at + ': expected object')
        return False
    if set(value) != fields:
        errors.append(at + ': missing/unknown fields ' + ','.join(sorted(set(value) ^ fields)))
        return False
    return True


def _source_ref(ref: dict, files: dict, at: str, errors: list[str]) -> None:
    fields = {'file', 'sha256', 'start_line', 'end_line', 'start_byte', 'end_byte', 'span_sha256'}
    if not _closed(ref, fields, at, errors):
        return
    path = ref['file']
    if path not in files:
        errors.append(at + ': unknown source file ' + str(path))
        return
    raw = files[path]['source_text'].encode()
    a, b = ref['start_byte'], ref['end_byte']
    if type(a) is not int or type(b) is not int or not 0 <= a < b <= len(raw):
        errors.append(at + ': invalid half-open source span')
        return
    if ref['sha256'] != _sha(raw) or ref['span_sha256'] != _sha(raw[a:b]):
        errors.append(at + ': source/span hash mismatch')
    if ref['start_line'] != raw[:a].count(b'\n') + 1 or ref['end_line'] != raw[:b-1].count(b'\n') + 1:
        errors.append(at + ': source line/byte mismatch')


def _anchor(ref: dict, root: Path, allowed: set[str], at: str, errors: list[str]) -> None:
    if not isinstance(ref, dict) or 'path' not in ref:
        errors.append(at + ': invalid source anchor')
        return
    path = ref['path']
    if not _safe_path(path) or path not in allowed:
        errors.append(at + ': private/sibling/unlisted source path ' + str(path))
        return
    try:
        raw = _read(root, path)
    except (OSError, ValueError) as exc:
        errors.append(at + ': unreadable source anchor ' + str(exc))
        return
    lines = raw.splitlines(keepends=True)
    a, b = ref['start_line'], ref['end_line']
    if not 1 <= a <= b <= len(lines) or ref['sha256'] != _sha(raw) or ref['span_sha256'] != _sha(b''.join(lines[a-1:b])):
        errors.append(at + ': source anchor hash/lines changed ' + path)


def _denominator_errors(d: dict) -> list[str]:
    errors = []
    if not _closed(d, {'format_version', 'upstream', 'files', 'entities', 'exclusions'}, 'denominator', errors):
        return errors
    if d['format_version'] != 1:
        errors.append('denominator.format_version: unsupported')
    if _sha(_formatted(d)) != SNAPSHOT_SHA256:
        errors.append('denominator: immutable snapshot seal mismatch; source review required')
    upstream = d['upstream']
    if not _closed(upstream, {'version', 'tag', 'recorded_commit', 'recorded_commit_provenance', 'archive_url', 'archive_sha256', 'inclusion_policy', 'version_nodes', 'licenses', 'external_dependencies'}, 'upstream', errors):
        return errors
    if upstream['archive_sha256'] != ARCHIVE_SHA256 or upstream['version'] != '1.7.0' or upstream['tag'] != 'v1.7.0':
        errors.append('upstream: archive/version pin mismatch')
    files = {f.get('path'): f for f in d['files'] if isinstance(f, dict)}
    entities = {e.get('id'): e for e in d['entities'] if isinstance(e, dict)}
    exclusions = {e.get('id'): e for e in d['exclusions'] if isinstance(e, dict)}
    if len(files) != len(d['files']) or len(entities) != len(d['entities']) or len(exclusions) != len(d['exclusions']):
        errors.append('denominator: duplicate source/entity/exclusion ID')
    for missing in sorted(set(ENTITY_SEALS) - set(entities)):
        errors.append('source census missing entity ' + missing)
    for extra in sorted(set(entities) - set(ENTITY_SEALS)):
        errors.append('source census unreviewed entity ' + extra)
    for eid, e in sorted(entities.items()):
        if eid in ENTITY_SEALS and _sha(_canonical(e)) != ENTITY_SEALS[eid]:
            errors.append(eid + ': frozen signature/alternative/member/dependency identity changed')
        fields = {'id', 'kind', 'name', 'source_refs', 'declaration', 'version_nodes', 'requires', 'alias_of'}
        if e.get('kind') in ('record', 'enum'):
            fields.add('members')
        if not _closed(e, fields, str(eid), errors):
            continue
        if e['kind'] not in KINDS:
            errors.append(str(eid) + ': unknown entity kind')
        if not _closed(e['declaration'], {'scope', 'alternatives'}, str(eid) + '.declaration', errors):
            continue
        for i, alt in enumerate(e['declaration']['alternatives']):
            if not _closed(alt, {'source_ref', 'source_text', 'conditions', 'parsed'}, str(eid) + '.alternative', errors):
                continue
            _source_ref(alt['source_ref'], files, str(eid) + '.alternative[' + str(i) + ']', errors)
            ref = alt['source_ref']
            if ref['file'] in files and files[ref['file']]['source_text'].encode()[ref['start_byte']:ref['end_byte']] != alt['source_text'].encode():
                errors.append(str(eid) + ': alternative source text mismatch')
        for ref in e['source_refs']:
            _source_ref(ref, files, str(eid), errors)
    for xid, exclusion in sorted(exclusions.items()):
        if not _closed(exclusion, {'id','source_refs','classification','public_owner','reason','definitions','requires'}, xid, errors):
            continue
        for ref in exclusion['source_refs']:
            _source_ref(ref, files, xid, errors)
        for definition in exclusion['definitions']:
            _closed(definition, {'source_text','conditions'}, xid + '.definition', errors)
    external = {e['id'] for e in upstream['external_dependencies']}
    for e in upstream['external_dependencies']:
        if not _closed(e, {'id','name','origin_include_or_builtin','grammatical_roles','uses','abi_binding','later_obligation'}, e['id'], errors):
            continue
        for use in e['uses']:
            if _closed(use, {'owner','grammatical_role','source_ref'}, e['id'] + '.use', errors):
                _source_ref(use['source_ref'], files, e['id'], errors)
        if e['abi_binding'] != 'NOT_QUALIFIED':
            errors.append(e['id'] + ': external ABI binding cannot be inferred')
    for eid, e in sorted({**entities, **exclusions}.items()):
        for dep in e.get('requires', []):
            if dep not in entities and dep not in exclusions and dep not in external:
                errors.append(eid + ': dangling dependency ' + dep)
        for member in e.get('members', []):
            if member not in entities:
                errors.append(eid + ': missing member ' + member)
        if e.get('alias_of') is not None:
            target = e['alias_of'];seen = {eid}
            while target is not None:
                if target not in entities:
                    errors.append(eid + ': dangling alias ' + target);break
                if target in seen:
                    errors.append(eid + ': circular alias');break
                seen.add(target);target = entities[target]['alias_of']
    for path in sorted(set(FILE_SEALS) - set(files)):
        errors.append('source file missing ' + path)
    for path, f in sorted(files.items()):
        if not _closed(f, {'path', 'sha256', 'source_text', 'notices', 'license_refs', 'role', 'includes', 'units'}, str(path), errors):
            continue
        if path not in FILE_SEALS or _sha(_canonical(f)) != FILE_SEALS.get(path):
            errors.append(str(path) + ': frozen source/ownership/policy identity changed')
        if not _safe_path(path) or _sha(f['source_text'].encode()) != f['sha256']:
            errors.append(str(path) + ': unsafe path/source hash mismatch')
        if path in HOST_HEADERS and f['role'] != 'host_shared':
            errors.append(str(path) + ': required host/shared source role lost')
        for notice in f['notices']:
            if _closed(notice, {'source_ref','text'}, str(path) + '.notice', errors):
                _source_ref(notice['source_ref'], files, str(path) + '.notice', errors)
        for include in f['includes']:
            if _closed(include, {'tokens','source_ref','conditions'}, str(path) + '.include', errors):
                _source_ref(include['source_ref'], files, str(path) + '.include', errors)
        unit_ids = {u['id']: u for u in f['units']}
        cursor = 0
        top = sorted((u for u in f['units'] if u['parent'] is None), key=lambda u:u['start_byte'])
        for unit in top:
            if unit['start_byte'] != cursor:
                errors.append(str(path) + ': source ownership gap/overlap at ' + str(cursor))
            cursor = unit['end_byte']
        if cursor != len(f['source_text'].encode()):
            errors.append(str(path) + ': incomplete source ownership at EOF')
        siblings = {}
        for unit in f['units']:
            if not _closed(unit, {'id', 'kind', 'start_byte', 'end_byte', 'conditions', 'parent', 'entity_ids', 'exclusion_ids'}, str(path) + '.unit', errors):
                continue
            if unit['parent'] is not None:
                parent = unit_ids.get(unit['parent'])
                if parent is None or not parent['start_byte'] <= unit['start_byte'] < unit['end_byte'] <= parent['end_byte']:
                    errors.append(unit['id'] + ': invalid source parent')
                siblings.setdefault(unit['parent'], []).append(unit)
            for eid in unit['entity_ids']:
                if eid not in entities:
                    errors.append(unit['id'] + ': source owner missing entity ' + eid)
            for xid in unit['exclusion_ids']:
                if xid not in exclusions:
                    errors.append(unit['id'] + ': source owner missing exclusion ' + xid)
        for children in siblings.values():
            children.sort(key=lambda u:(u['start_byte'],u['end_byte']))
            for a, b in zip(children, children[1:]):
                if a['end_byte'] > b['start_byte']:
                    errors.append(a['id'] + ': sibling ownership overlap with ' + b['id'])
    globals_ = {}
    for node in upstream['version_nodes']:
        for name in node['globals']:
            if name in globals_:
                errors.append('duplicate version-map global ' + name)
            globals_[name] = node['name']
    if len(globals_) != 356 or len(upstream['version_nodes']) != 25:
        errors.append('upstream version-map 356/25 identity changed')
    for name, node in sorted(globals_.items()):
        entity = entities.get('function:' + name)
        if entity is None or entity['version_nodes'] != [node]:
            errors.append('function:' + name + ': missing/reversioned map declaration')
    for eid, e in entities.items():
        if e['kind'] != 'function' and e['version_nodes']:
            errors.append(eid + ': header-only entity has fictitious export node')
    return errors


def _option_ids(e: dict, entities: dict) -> set[str]:
    result = set();seen = set()
    def visit(eid):
        if eid in seen or eid not in entities:
            return
        seen.add(eid);item = entities[eid]
        if item['kind'] == 'member':
            result.add(eid)
        if item['kind'] == 'record' and (item['name'].endswith('_opts') or eid == e['id'] or '.@' in item['name']):
            for member in item.get('members', []):
                visit(member)
        if item['kind'] == 'member':
            for alt in item['declaration']['alternatives']:
                for member in alt['parsed'].get('record_members', []):
                    visit(member)
        if item['kind'] in ('function', 'inline', 'callback'):
            for dep in item['requires']:
                if dep.startswith('record:') and dep in entities and entities[dep]['name'].endswith('_opts'):
                    visit(dep)
    visit(e['id'])
    return result


def validate_inventory(coverage: dict, denominator: dict, repository_root: Path) -> list[str]:
    """Return deterministic source-contract errors; read only named local source inputs."""
    errors = []
    try:
        schema_raw = _read(repository_root, SCHEMA_PATH)
        schema = json.loads(schema_raw)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return ['schema: unreadable ' + str(exc)]
    if _sha(schema_raw) != SCHEMA_SHA256:
        errors.append('schema: immutable vocabulary seal mismatch')
    errors += _schema_errors(coverage, schema, schema)
    def public_strings(value, at):
        if isinstance(value, dict):
            for key, item in value.items():
                public_strings(item, at + '.' + key)
        elif isinstance(value, list):
            for index, item in enumerate(value):
                public_strings(item, at + '[' + str(index) + ']')
        elif isinstance(value, str) and any(marker in value for marker in ('/work/', '/home/', '../')):
            errors.append(at + ': private/sibling provenance text')
    public_strings(coverage, 'coverage')
    if errors:
        return sorted(set(errors))
    try:
        errors += _denominator_errors(denominator)
    except (KeyError, TypeError, ValueError, IndexError, AttributeError, RecursionError) as exc:
        errors.append('denominator: malformed source contract ' + str(exc))
        return sorted(set(errors))
    if coverage['upstream_snapshot']['sha256'] != SNAPSHOT_SHA256:
        errors.append('upstream_snapshot.sha256: immutable snapshot pin mismatch')
    manifest = coverage['implementation_snapshot']['sources']
    if _sha(_canonical(manifest)) != SOURCE_MANIFEST_SHA256:
        errors.append('implementation_snapshot.sources: exact source allowlist changed')
    if coverage['implementation_snapshot']['base_revision'] != '36bb6c080b473e5cf3f0f06f59a16e23bec7dc9f':
        errors.append('implementation_snapshot.base_revision: changed baseline')
    allowed = set(IMPLEMENTATION_SOURCES)
    for entry in manifest:
        if entry['path'] not in allowed or not _safe_path(entry['path']):
            errors.append('implementation_snapshot: private/sibling/unlisted source path ' + entry['path'])
            continue
        try:
            if _sha(_read(repository_root, entry['path'])) != entry['sha256']:
                errors.append('implementation_snapshot: source changed ' + entry['path'])
        except (OSError, ValueError) as exc:
            errors.append('implementation_snapshot: unreadable source ' + str(exc))
    if len({e['path'] for e in manifest}) != len(manifest):
        errors.append('implementation_snapshot.sources: duplicate path')
    entities = {e['id']:e for e in denominator['entities']}
    rows = {r['id']:r for r in coverage['rows']}
    if len(rows) != len(coverage['rows']):
        errors.append('rows: duplicate ID')
    for eid in sorted(set(entities) - set(rows)):
        errors.append(eid + ': missing coverage row')
    for eid in sorted(set(rows) - set(entities)):
        errors.append(eid + ': unknown coverage row')
    bridge_names = set(SESSION_EXPORTS) | set(GENERIC_EXPORTS)
    for eid, row in sorted(rows.items()):
        entity = entities.get(eid)
        if entity is None:
            continue
        if row['applicability'] != 'required':
            errors.append(eid + ': admitted entity cannot be reclassified excluded without source policy review')
        callable_ = entity['kind'] in ('function', 'inline', 'callback')
        mapping = {key:row[key] for key in ('raw_declaration','forwarding_adapter','typed_workflow')}
        if eid in ROW_MAPPING_SEALS and _sha(_canonical(mapping)) != ROW_MAPPING_SEALS[eid]:
            errors.append(eid + ': source mapping/option disposition/restrictions changed; review source contract')
        if callable_ and row['raw_declaration'] != {'status':'ABSENT','refs':[]}:
            errors.append(eid + ': raw declaration is absent; bridge source use does not imply raw binding')
        if not callable_ and row['raw_declaration']['status'] != 'NOT_APPLICABLE':
            errors.append(eid + ': noncallable requires source representation mapping')
        for column in ('raw_declaration', 'forwarding_adapter', 'typed_workflow'):
            data = row[column]
            for ref in data['refs']:
                _anchor(ref, repository_root, allowed, eid + '.' + column, errors)
            if column == 'raw_declaration':
                continue
            if data['status'] == 'SOURCE_PRESENT_COMPLETE':
                errors.append(eid + '.' + column + ': complete adaptation is not qualified in this snapshot')
            if data['status'] == 'SOURCE_PRESENT_PARTIAL' and (not data['refs'] or not data['restrictions'] or not data['bridge_symbols']):
                errors.append(eid + '.' + column + ': partial mapping needs source, restrictions and bridge symbols')
            if data['status'] == 'ABSENT' and data['refs']:
                errors.append(eid + '.' + column + ': absent mapping carries source claim')
            if data['status'] == 'NOT_APPLICABLE' and (callable_ or not data['restrictions']):
                errors.append(eid + '.' + column + ': invalid applicability/representation')
            if set(data['bridge_symbols']) - bridge_names:
                errors.append(eid + '.' + column + ': unknown bridge symbol')
            if entity['kind'] == 'alias' and data['status'].startswith('SOURCE_PRESENT'):
                errors.append(eid + ': alias spelling is not an implementation pass')
        expected_options = _option_ids(entity, entities)
        options = row['forwarding_adapter']['option_members']
        observed_options = {o['id'] for o in options}
        for mid in sorted(expected_options ^ observed_options):
            errors.append(eid + ': option member disposition missing/unknown ' + mid)
        if len(options) != len(observed_options):
            errors.append(eid + ': duplicate option member disposition')
        for option in options:
            mid = option['id']
            if mid in entities and option['source_refs'] != entities[mid]['source_refs']:
                errors.append(eid + ': option source identity changed ' + mid)
            for ref in option['refs']:
                _anchor(ref, repository_root, allowed, eid + '.option.' + mid, errors)
            if option['disposition'] != 'NOT_EXPOSED' and not option['refs']:
                errors.append(eid + ': option mapping lacks source ' + mid)
        observed_layers = [cell['layer'] for cell in row['evidence_cells']]
        if sorted(observed_layers) != sorted(LAYERS):
            errors.append(eid + ': missing/duplicate NOT_RUN evidence layer')
        for cell in row['evidence_cells']:
            if cell['id'] != cell['layer']:
                errors.append(eid + ': evidence cell ID/layer mismatch')
            if cell['outcome'] != 'NOT_RUN' or cell['evidence_refs']:
                errors.append(eid + '.' + cell['layer'] + ': runtime/ABI/test-name evidence promotion; exact independently qualified result required')
        for column, refs in row['tests'].items():
            for ref in refs:
                _anchor(ref, repository_root, allowed, eid + '.tests.' + column, errors)
        if row['blocker'] is None:
            errors.append(eid + ': required work blocker cannot disappear')
    abi = coverage['bridge_abi']
    if _sha(_canonical(abi)) != BRIDGE_SHA256:
        errors.append('bridge_abi: exact source ABI manifest changed')
    expected_nodes = {name:'LIBBPF_MOJO_1' for name in SESSION_EXPORTS}
    expected_nodes.update({name:'LIBBPF_MOJO_GENERIC_1' for name in GENERIC_EXPORTS})
    observed = {}
    for export in abi['exports']:
        name = export['name']
        if name in observed:
            errors.append('bridge_abi: duplicate export ' + name)
        observed[name] = export['version_node']
        if expected_nodes.get(name) != export['version_node']:
            errors.append('bridge_abi: lost/reversioned/unreviewed export ' + name)
        if name in BRIDGE_SIGNATURES and export['signature'] != BRIDGE_SIGNATURES[name]:
            errors.append('bridge_abi: source signature changed ' + name)
        for ref in export['source_refs']:
            _anchor(ref, repository_root, allowed, 'bridge_abi.' + name, errors)
    for name in sorted(set(expected_nodes) - set(observed)):
        errors.append('bridge_abi: missing original/generic export ' + name)
    for type_ in abi['types']:
        for ref in type_['source_refs']:
            _anchor(ref, repository_root, allowed, 'bridge_abi.' + type_['id'], errors)
    for name in ('frozen_old_header', 'export_checker'):
        _anchor(abi[name], repository_root, allowed, 'bridge_abi.' + name, errors)
    if _sha(_canonical(coverage['compatibility_cells'])) != COMPATIBILITY_SHA256:
        errors.append('compatibility_cells: required NOT_RUN profile/version cell changed or lost')
    return sorted(set(errors))


class InventoryTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.d = json.loads(_read(ROOT, SNAPSHOT_PATH))
        cls.c = json.loads(_read(ROOT, 'docs/api-coverage.json'))
        cls.schema = json.loads(_read(ROOT, SCHEMA_PATH))

    def reject(self, mutate, needle, denominator=False):
        c, d = copy.deepcopy(self.c), copy.deepcopy(self.d)
        mutate(d if denominator else c)
        errors = validate_inventory(c, d, ROOT)
        self.assertTrue(any(needle in error for error in errors), (needle, errors[:12]))

    @staticmethod
    def row(c, eid):
        return next(r for r in c['rows'] if r['id'] == eid)

    @staticmethod
    def entity(d, eid):
        return next(e for e in d['entities'] if e['id'] == eid)

    def test_public_header_union_has_owned_rows(self):
        self.assertEqual([], validate_inventory(self.c, self.d, ROOT))
        roles = {f['path']:f['role'] for f in self.d['files']}
        self.assertEqual(HOST_HEADERS, {p for p, role in roles.items() if role == 'host_shared'})
        self.assertEqual(13, len(HOST_HEADERS | PRODUCER_HEADERS | {'src/skel_internal.h'}))
        self.assertEqual({e['id'] for e in self.d['entities']}, {r['id'] for r in self.c['rows']})

    def test_census_rejects_export_and_header_only_omissions(self):
        ids = ('function:bpf_object__open_mem','inline:btf_kind','callback:ring_buffer_sample_fn','macro:LIBBPF_OPTS','macro:bpf_htons','alias:bpf_map__for_each','macro:BPF_TAG_SIZE','macro:BPF_OBJ_NAME_LEN')
        for eid in ids:
            with self.subTest(eid=eid):
                self.reject(lambda d: d['entities'].__setitem__(slice(None), [e for e in d['entities'] if e['id'] != eid]), 'source owner missing entity ' + eid, True)

    def test_entity_and_coverage_deletion_cannot_self_consistently_shrink(self):
        c, d = copy.deepcopy(self.c), copy.deepcopy(self.d)
        eid = 'inline:btf_kind'
        d['entities'] = [e for e in d['entities'] if e['id'] != eid]
        c['rows'] = [r for r in c['rows'] if r['id'] != eid]
        c['upstream_snapshot']['sha256'] = _sha(_formatted(d))
        errors = validate_inventory(c, d, ROOT)
        self.assertTrue(any('source owner missing entity ' + eid in e for e in errors))

    def test_coverage_omissions_and_duplicate_ids_rejected(self):
        for eid in ('function:bpf_object__open_mem','inline:btf_kind','callback:btf_dump_printf_fn_t','member:bpf_test_run_opts.repeat','macro:LIBBPF_OPTS','alias:bpf_map__for_each'):
            with self.subTest(eid=eid):
                self.reject(lambda c: c['rows'].__setitem__(slice(None), [r for r in c['rows'] if r['id'] != eid]), eid + ': missing coverage row')
        self.reject(lambda c: c['rows'].append(copy.deepcopy(c['rows'][0])), 'rows: duplicate ID')
        self.reject(lambda d: d['entities'].append(copy.deepcopy(d['entities'][0])), 'duplicate source/entity/exclusion', True)

    def test_option_member_disposition_is_complete(self):
        eid = 'record:bpf_link_create_opts'
        self.reject(lambda c: self.row(c,eid)['forwarding_adapter']['option_members'].pop(), 'option member disposition missing/unknown')
        eid = 'function:bpf_prog_test_run_opts'
        self.reject(lambda c: self.row(c,eid)['forwarding_adapter']['option_members'].pop(), 'option member disposition missing/unknown')

    def test_option_members_and_last_field_are_lossless(self):
        for eid in ('member:perf_buffer_raw_opts.@padding1','member:perf_buffer_raw_opts.@padding2'):
            self.assertIn(eid, ENTITY_SEALS)
        repeat = self.entity(self.d, 'member:bpf_test_run_opts.repeat')
        self.assertEqual(['int'], repeat['declaration']['alternatives'][0]['parsed']['type']['specifiers'])
        tail = self.entity(self.d,'macro:bpf_link_create_opts__last_field')
        self.assertEqual(['uprobe_multi','.','pid'], tail['declaration']['alternatives'][0]['parsed']['replacement_tokens'])
        self.reject(lambda d: self.entity(d,'member:bpf_test_run_opts.repeat')['declaration']['alternatives'][0]['parsed']['type'].__setitem__('specifiers',['unsigned','int']), 'member:bpf_test_run_opts.repeat: frozen signature', True)
        self.reject(lambda d: self.entity(d,'record:bpf_link_create_opts').__setitem__('members',[]), 'record:bpf_link_create_opts: frozen signature', True)
        self.reject(lambda d: self.entity(d,'macro:bpf_link_create_opts__last_field')['declaration']['alternatives'][0]['parsed'].__setitem__('replacement_tokens',['cgroup','.','expected_revision']), 'macro:bpf_link_create_opts__last_field: frozen signature', True)

    def test_callback_and_conditional_signature_drift_rejected(self):
        self.reject(lambda d: self.entity(d,'function:bpf_enable_stats')['declaration']['alternatives'].pop(), 'function:bpf_enable_stats: frozen signature', True)
        self.reject(lambda d: self.entity(d,'callback:btf_dump_printf_fn_t')['declaration']['alternatives'][0]['parsed']['parameters'][-1]['type'].__setitem__('specifiers',['int']), 'callback:btf_dump_printf_fn_t: frozen signature', True)
        self.reject(lambda d: self.entity(d,'macro:BTF_KIND_FUNC')['declaration']['alternatives'][0].__setitem__('conditions',[]), 'macro:BTF_KIND_FUNC: frozen signature', True)

    def test_macro_alias_and_external_dependencies_are_owned(self):
        for member, macro in (('member:bpf_prog_info.tag','macro:BPF_TAG_SIZE'), ('member:bpf_prog_info.name','macro:BPF_OBJ_NAME_LEN'), ('member:bpf_map_info.name','macro:BPF_OBJ_NAME_LEN')):
            self.assertIn(macro, self.entity(self.d,member)['requires'])
            self.reject(lambda d:self.entity(d,member)['requires'].remove(macro), member + ': frozen signature', True)
        btf_int = next(e for e in self.d['entities'] if e['kind']=='enumerator' and e['name'].endswith('.BTF_KIND_INT'))
        btf_func = next(e for e in self.d['entities'] if e['kind']=='enumerator' and e['name'].endswith('.BTF_KIND_FUNC'))
        self.assertIn(btf_int['id'],self.entity(self.d,'inline:btf_is_int')['requires'])
        self.assertIn(btf_func['id'],self.entity(self.d,'inline:btf_is_func')['requires'])
        self.assertIn('macro:BTF_KIND_FUNC',self.entity(self.d,'inline:btf_is_func')['requires'])
        self.reject(lambda d:self.entity(d,'inline:btf_is_int')['requires'].remove(btf_int['id']), 'inline:btf_is_int: frozen signature', True)
        self.reject(lambda d: self.entity(d,'alias:bpf_map__for_each').__setitem__('alias_of','macro:no_such_macro'), 'dangling alias', True)
        self.reject(lambda d: d['exclusions'].__setitem__(slice(None),[e for e in d['exclusions'] if e['id'] != 'exclusion:macro:__bpf_htons']), 'source owner missing exclusion exclusion:macro:__bpf_htons', True)
        self.reject(lambda d: next(f for f in d['files'] if f['path']=='src/bpf_endian.h').__setitem__('role','kernel_program_headers'), 'required host/shared source role lost', True)
        self.reject(lambda d: d['upstream']['external_dependencies'][0].__setitem__('abi_binding','uint64_t'), 'external ABI binding cannot be inferred', True)

    def test_archive_map_and_source_partition_fail_closed(self):
        self.reject(lambda d: d['upstream'].__setitem__('archive_sha256','0'*64), 'archive/version pin mismatch', True)
        self.reject(lambda d: d['upstream']['version_nodes'][0]['globals'].append(d['upstream']['version_nodes'][0]['globals'][0]), 'duplicate version-map global', True)
        self.reject(lambda d: next(f for f in d['files'] if f['path']=='src/bpf.h')['units'].pop(0), 'source ownership gap/overlap', True)
        def overlap(d):
            f=next(f for f in d['files'] if f['path']=='src/bpf.h')
            children=[u for u in f['units'] if u['parent'] is not None]
            siblings=[u for u in children if u['parent']==children[0]['parent']]
            self.assertGreaterEqual(len(siblings),2)
            siblings[1]['start_byte']=siblings[0]['start_byte']
        self.reject(overlap,'sibling ownership overlap',True)

    def test_bridge_manifest_is_exact_11_plus_20(self):
        self.assertEqual(31,len(self.c['bridge_abi']['exports']))
        self.assertEqual(set(SESSION_EXPORTS),{e['name'] for e in self.c['bridge_abi']['exports'] if e['version_node']=='LIBBPF_MOJO_1'})
        self.assertEqual(set(GENERIC_EXPORTS),{e['name'] for e in self.c['bridge_abi']['exports'] if e['version_node']=='LIBBPF_MOJO_GENERIC_1'})
        self.reject(lambda c:c['bridge_abi']['exports'].pop(),'missing original/generic export')

    def test_no_lost_or_reversioned_old_export(self):
        self.reject(lambda c:next(e for e in c['bridge_abi']['exports'] if e['name']=='lmb_open').__setitem__('version_node','LIBBPF_MOJO_GENERIC_1'),'lost/reversioned/unreviewed export lmb_open')
        self.reject(lambda c:next(e for e in c['bridge_abi']['exports'] if e['name']=='lmb_object_open_v1').__setitem__('signature','int changed(void);'),'source signature changed lmb_object_open_v1')

    def test_no_leaked_bpf_or_internal_symbol(self):
        def add(c):
            entry=copy.deepcopy(c['bridge_abi']['exports'][0]);entry['name']='bpf_object__open_mem';c['bridge_abi']['exports'].append(entry)
        self.reject(add,'lost/reversioned/unreviewed export bpf_object__open_mem')

    def test_source_use_does_not_imply_raw_binding(self):
        self.reject(lambda c:self.row(c,'function:bpf_object__open_mem')['raw_declaration'].__setitem__('status','SOURCE_PRESENT'),'raw declaration is absent')
        self.reject(lambda c:self.row(c,'function:bpf_prog_test_run_opts')['forwarding_adapter'].__setitem__('status','SOURCE_PRESENT_COMPLETE'),'complete adaptation is not qualified')

    def test_alias_not_an_implementation_pass(self):
        self.reject(lambda c:self.row(c,'alias:bpf_map__for_each')['forwarding_adapter'].__setitem__('status','SOURCE_PRESENT_PARTIAL'),'alias spelling is not an implementation pass')

    def test_test_name_does_not_imply_runtime_pass(self):
        eid='function:bpf_object__open_mem'
        def promote(c):
            cell=next(x for x in self.row(c,eid)['evidence_cells'] if x['layer']=='target_runtime');cell['outcome']='PASS';cell['evidence_refs']=[copy.deepcopy(c['bridge_abi']['frozen_old_header'])]
        self.reject(promote,'runtime/ABI/test-name evidence promotion')

    def test_not_run_cell_cannot_disappear(self):
        self.reject(lambda c:self.row(c,'function:bpf_object__open_mem')['evidence_cells'].pop(),'missing/duplicate NOT_RUN evidence layer')
        self.reject(lambda c:c['compatibility_cells'].pop(),'required NOT_RUN profile/version cell changed or lost')
        self.reject(lambda c:self.row(c,'function:bpf_prog_test_run_opts')['forwarding_adapter']['option_members'][0].__setitem__('disposition','FORWARDED'),'source mapping/option disposition/restrictions changed')

    def test_upstream_archive_or_snapshot_hash_drift_rejected(self):
        self.reject(lambda c:c['upstream_snapshot'].__setitem__('sha256','f'*64),'immutable snapshot pin mismatch')
        self.reject(lambda d:next(f for f in d['files'] if f['path']=='src/libbpf.h').__setitem__('sha256','f'*64),'source/ownership/policy identity changed',True)

    def test_private_or_sibling_provenance_rejected(self):
        for path in ('../sibling/source.c','/private/source.c','build/source.c'):
            with self.subTest(path=path):
                self.reject(lambda c:c['implementation_snapshot']['sources'][0].__setitem__('path',path),'private/sibling')

    def test_unknown_schema_fields_rejected(self):
        self.reject(lambda c:c.__setitem__('support_percentage',100),'unknown schema field')
        self.reject(lambda c:self.row(c,'inline:btf_kind')['raw_declaration'].__setitem__('runtime_pass',True),'unknown schema field')
        self.reject(lambda c:c['bridge_abi']['types'][0]['declaration'].__setitem__('guessed_offset',8),'unknown schema field')
        self.reject(lambda d:self.entity(d,'inline:btf_kind').__setitem__('runtime_pass',True),'missing/unknown fields',True)

    def test_schema_and_semantic_validator_agree_on_malformed_documents(self):
        mutants=[]
        for mutate in (lambda c:c.__setitem__('extra',True),lambda c:c.__setitem__('schema_version',True),lambda c:c['rows'][0].__setitem__('workflow','private-stage'),lambda c:c['rows'][0]['tests'].__setitem__('positive_refs','test_name'),lambda c:c['rows'][0]['evidence_cells'][0].__setitem__('outcome','SKIP')):
            c=copy.deepcopy(self.c);mutate(c);mutants.append(c)
        for c in mutants:
            self.assertTrue(_schema_errors(c,self.schema,self.schema))
            self.assertTrue(validate_inventory(c,self.d,ROOT))

    def test_exact_source_seals_and_public_paths(self):
        self.assertEqual(SNAPSHOT_SHA256,_sha(_read(ROOT,SNAPSHOT_PATH)))
        self.assertEqual(SCHEMA_SHA256,_sha(_read(ROOT,SCHEMA_PATH)))
        self.assertEqual(sorted(IMPLEMENTATION_SOURCES),sorted(e['path'] for e in self.c['implementation_snapshot']['sources']))
        # Retained upstream notices and license text are source material, not relicensed first-party code.
        license_text={f['path']:f['source_text'] for f in self.d['files'] if f['path'].startswith('LICENSE')}
        for license_ in self.d['upstream']['licenses']:
            self.assertEqual(license_['text'],license_text[license_['path']])
            self.assertEqual(license_['sha256'],_sha(license_['text'].encode()))


